#include "nvfs_private.h"

/*==========================================================================*/
/*      D E F I N E S  -  E N U M E R A T I O N S  -  T Y P E D E F S       */
/*==========================================================================*/

/*==========================================================================*/
/*                  F U N C T I O N   P R O T O T Y P E S                   */
/*==========================================================================*/

/*==========================================================================*/
/*                            V A R I A B L E S                             */
/*==========================================================================*/

/*==========================================================================*/
/*                 F U N C T I O N   D E F I N I T I O N S                  */
/*==========================================================================*/
                                                   
NVFS_Status nvfs_wr_create (NVFS_Entry_Name const entry_name , const void * const ram_srce , UInt16 entry_size)
{
  NVFS_Status nvfs_status = NVFS_IRQ_CALL_FAILED ;

  if (nvfs_atomic_request ())
    {
      nvfs_status = nvfs_wr (entry_name , ram_srce) ;

      if (nvfs_status == NVFS_NAME_NOT_FOUND)
        {
          nvfs_status =  nvfs_create (entry_name , entry_size) ;

          if (nvfs_status == NVFS_OK)
            {
              nvfs_status = nvfs_wr (entry_name , ram_srce) ;
            }
        }
    
      nvfs_atomic_release () ;
    }

  return nvfs_status ;
}

